SELECT FROM DOC_LAW_MAPPINGS m JOIN COMPANY_DOCUMENTS d ON d.ID = m.DOCUMENT_ID JOIN TRACKED_LAWS l ON l.ID = m.TRACKED_LAW_ID
m.DOCUMENT_ID = #{documentId}
AND m.TRACKED_LAW_ID = #{trackedLawId}
ORDER BY d.TITLE, l.NAME

SELECT ID, DOCUMENT_ID, TRACKED_LAW_ID, NOTE, CREATED_AT
  FROM DOC_LAW_MAPPINGS
 WHERE DOCUMENT_ID = #{documentId}
   AND TRACKED_LAW_ID = #{trackedLawId}

SELECT m.TRACKED_LAW_ID, d.TITLE AS DOCUMENT_TITLE FROM DOC_LAW_MAPPINGS m JOIN COMPANY_DOCUMENTS d ON d.ID = m.DOCUMENT_ID WHERE m.TRACKED_LAW_ID IN
#{id}
ORDER BY m.TRACKED_LAW_ID, d.TITLE
